# Own-wording items of Steinhardt's Guide to the Eldritch Hunt (2024). Row shape as tvss_item.py and tghp_item.py.
# 7 weapons come from the source baseitems (stats from the source, notes in WDESC). Ammunition and ammo packs are GEAR rows.
# Moongold Weapon and Moongold Ammunition are magicvariants, written as item rows.
ITEMS = []; SP = {}; WPN = {}; GEAR = []
def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))

MASTERY = {}
WDESC = {
 "Blunderbuss": "Barrel (2) and Twinned Barrel: two barrels, fired one at a time or both as one attack that raises the damage die one step. Blaring: heard 100 ft away, Disadvantage on Stealth to Hide until your next turn. Spread Fire: no normal attack, it sprays a 20 ft Cone and each creature makes a Dexterity save (DC 8 plus Dexterity modifier plus Proficiency Bonus) or takes the weapon's damage. Ammo: Bullet.",
 "Flintlock": "Barrel (1): reload as an action, as part of the Attack action in place of an attack, or as a Bonus Action since it is Light. Blaring: heard 100 ft away, Disadvantage on Stealth to Hide until your next turn. Ammo: Bullet.",
 "Pistol": "Barrel (6) and Fan Fire: as an action fire a number of bullets equal to your Dexterity modifier (min 2, up to the barrel), each shot after the first at a cumulative -3 and with no modifier added to damage. Your Speed is 0 until the end of your turn and long-range shots miss. A 1 jams the weapon (DC 15 Dexterity (Sleight of Hand) as an action or 1 hour of mending, a failure breaks it). Blaring: heard 100 ft away, Disadvantage on Stealth to Hide until your next turn. Ammo: Bullet.",
 "Rifle": "Barrel (2) and Twinned Barrel: two barrels, fired one at a time or both as one attack that raises the damage die one step. Steady: as a Bonus Action if you have not moved, add your Proficiency Bonus to your next attack roll this turn and ignore long range Disadvantage, but your Speed is halved until the end of the turn. Blaring: heard 100 ft away, Disadvantage on Stealth to Hide until your next turn. Ammo: Bullet.",
 "Cannon": "Artillery: use Strength for attack and damage rolls, and it needs ammunition. Reload takes an action. After a fight, spend 1 minute to recover half the ammo you used (round down). Booming: heard 500 ft away, you automatically fail Stealth to Hide until your next turn, and creatures in the sound have automatic success on Perception checks against you. Ammo: Cannonball.",
}

# ---- magic items
add("Bag of Cannonballs", "Wondrous Item", "Uncommon", 0, "A bag linked to an extradimensional space that never weighs more than 3 lb. It holds up to 100 Cannonballs or similar objects. You draw them out as from a plain sack, with no action.")
add("Damascena", "Wondrous Item", "Uncommon", 0, "A Scion device that burns lead bullets into blue flame that scorches the abhorrent. Magic action: project a 15-ft Cone of blue fire. Each creature in it makes a Dexterity save (DC 11 plus your Proficiency Bonus) and takes 4d4 Fire damage plus a number of d4s equal to your Proficiency Bonus on a fail, or half as much on a success. Each use consumes 5 Bullets.")
add("Hand of Glory", "Wondrous Item", "Very Rare", 0, "The hand of a hanged scourgeborne, waxed and fermented in a casket. While you hold it, you can attune to one more magic item, and that item must be a ring worn on the hand. It has 5 charges and regains 1 at dusk. Each time you spend a charge, one finger burns down to a stump. Magic action while holding it: spend 1 charge to light a finger and cast Invisibility on yourself. For the duration the hand sheds Bright Light in a 10-ft radius that only you can see, and the spell ends early if you snuff the flame (no action). While Invisible this way, you can cast Knock at will on objects within the Bright Light.", ch=[5, "1", "dusk"])
SP["Hand of Glory"] = {"sp": [["Invisibility", 2], ["Knock", 2]]}
add("Sanctified Cannon", "Weapon", "Uncommon", 0, "A Cannon (3d10 Bludgeoning, range 120/240 ft, Artillery, Booming, Two-Handed, Push mastery, uses Cannonballs). **Charged Shot.** Once on each of your turns when you take the Attack action, you can replace one Cannon attack with a charged shot. Each creature in a 120-ft-long, 5-ft-wide Line in front of you makes a Dexterity save (DC 8 plus your Strength modifier plus your Proficiency Bonus) or takes 3d12 Bludgeoning damage and has the Prone condition. You can do this only if you have not moved this turn, and your Speed is 0 until the end of the turn after you do.", base=["Cannon"])
WPN["Sanctified Cannon"] = {"d": "3d10", "t": "Bludgeoning", "cat": "M", "k": "R", "p": "Two-Handed", "m": "Push", "w": 90, "r": "120/240", "xw": 1}
add("Big Bertha", "Weapon", "Rare", 0, "A Cannon inlaid with moongold (3d10 Bludgeoning, range 120/240 ft, Artillery, Booming, Two-Handed, Push mastery, uses Cannonballs). You gain a +1 bonus to attack and damage rolls with it. It deals an extra 1d4 Bludgeoning damage to non-Humanoid creatures. Moongold guides in the dark, so creatures holding or wearing it have Advantage on saves against the Frightened condition and against Madness. **Infusion.** As a Bonus Action, turn the dials to charge your loaded ammo. Your next attack gains one benefit. Forceful: On a hit the target takes an extra 1d6 Bludgeoning damage and makes a DC 15 Strength save or is pushed 15 ft and knocked Prone. Or fire at your own feet while on solid ground to blast yourself up and land in a space of your choice within 30 ft of the blast. Incendiary: On a hit the target takes an extra 3d4 Fire damage. Unstable: On a hit the target takes an extra 1d8 Cold damage, and a 10-ft Emanation around it fills with arcane mist that is Difficult Terrain for 1 minute.", fx={"atk": 1, "dmg": 1}, xd=["Non-Humanoid: +1d4 Bludgeoning"], base=["Cannon"])
WPN["Big Bertha"] = {"d": "3d10", "t": "Bludgeoning", "cat": "M", "k": "R", "p": "Two-Handed", "m": "Push", "w": 90, "r": "120/240", "xw": 1}

# ---- magicvariants
add("Moongold Weapon", "Weapon", "Unknown", 0, "Any weapon except a Net, magic or not, can be moongilded. Moongold adds 1d4 to damage rolls against non-Humanoid creatures. It guides in the dark, so creatures holding or wearing it have Advantage on saves against the Frightened condition and against Madness. Moongilding one weapon costs 1000 gp more than the base price and covers the metal and the time and skill to plate it without dulling the weapon. The coating wears off if the weapon is not recoated within 3 months, ending its effects. Recoating before then costs 500 gp and resets the 3 months.", xd=["Non-Humanoid: +1d4"])
add("Moongold Ammunition", "Weapon", "Unknown", 0, "Any ammunition except an Energy Cell can be moongilded. Moongold adds 1d4 to damage rolls against non-Humanoid creatures. It guides in the dark, so creatures holding or wearing it have Advantage on saves against the Frightened condition and against Madness. Moongilding ten pieces of ammunition costs 1000 gp more than the base price. The coating wears off if the ammunition is not recoated within 3 months, ending its effects. Recoating before then costs 500 gp and resets the 3 months.", xd=["Non-Humanoid: +1d4"])

